<?php
declare(strict_types=1);
require_once __DIR__ . '/../../includes/security.php';
require_once __DIR__ . '/../../config/database.php';
require_module_access('redaccion.correo_retiro');

$clients = db()->query('SELECT id, business_name, ruc FROM clients ORDER BY business_name, id')->fetchAll();
$contacts = db()->query('SELECT id, client_id, name, position FROM client_contacts ORDER BY sort_order, name, id')->fetchAll();
$machines = db()->query("SELECT id, equipo, serie_placa FROM maquinarias WHERE estado = 1 ORDER BY equipo, serie_placa, id")->fetchAll();
$workers = db()->query("SELECT w.id, w.full_name, w.document_number,
    GROUP_CONCAT(DISTINCT p.name ORDER BY p.name SEPARATOR ', ') AS positions
    FROM workers w
    LEFT JOIN worker_positions wp ON wp.worker_id = w.id
    LEFT JOIN positions p ON p.id = wp.position_id
    GROUP BY w.id, w.full_name, w.document_number
    ORDER BY w.full_name, w.id")->fetchAll();
$signatureUser = current_user() ?? [];
$signatureName = trim((string) ($signatureUser['name'] ?? 'Usuario del sistema'));
$signatureRole = (string) ($signatureUser['role'] ?? '');
$signaturePosition = match ($signatureRole) {
    'Administrador' => 'Responsable de sistema',
    'Gestor' => 'Gestor de operaciones',
    'Personal' => 'Colaborador',
    default => 'Responsable de Life Maquinarias',
};
$signatureWorkerId = current_user_worker_id();
if ($signatureWorkerId) {
    $signaturePositionStmt = db()->prepare("SELECT GROUP_CONCAT(DISTINCT p.name ORDER BY p.name SEPARATOR ', ')
        FROM worker_positions wp
        INNER JOIN positions p ON p.id = wp.position_id
        WHERE wp.worker_id = :worker_id");
    $signaturePositionStmt->execute(['worker_id' => $signatureWorkerId]);
    $linkedPosition = trim((string) $signaturePositionStmt->fetchColumn());
    if ($linkedPosition !== '') {
        $signaturePosition = $linkedPosition;
    }
}
$signatureData = [
    'name' => $signatureName,
    'position' => $signaturePosition,
    'phone' => '924 838 134',
    'email' => 'informes@lifemaquinarias.com',
    'website' => 'https://lifemaquinarias.com',
    'logo' => APP_URL . '/img/logolife.png',
    'phoneIcon' => APP_URL . '/img/cel.png',
    'emailIcon' => APP_URL . '/img/correo.png',
    'webIcon' => APP_URL . '/img/web.png',
];

require __DIR__ . '/../../includes/header.php';
?>
