<script>
const ingressContacts=<?= json_encode($contacts, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?>,ingressMachines=<?= json_encode($machines, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?>,ingressSignature=<?= json_encode($signatureData, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?>,ingressClient=document.getElementById('ingressClient'),ingressContact=document.getElementById('ingressContact'),ingressDate=document.getElementById('ingressDate'),ingressPreview=document.getElementById('ingressMessagePreview'),ingressDefaultDate=<?= json_encode(date('Y-m-d')) ?>;
function escapeIngressHtml(value){const element=document.createElement('div');element.textContent=String(value||'');return element.innerHTML}function ingressDateText(value){if(!value)return '[fecha de ingreso]';const [year,month,day]=value.split('-');return day&&month&&year?`${day}/${month}/${year}`:value}function selectedIngressWorkers(){return [...document.querySelectorAll('.ingress-worker:checked')].map(input=>({name:input.dataset.name,document:input.dataset.document,position:input.dataset.position}))}function selectedIngressMachines(){const selectedIds=[...document.querySelectorAll('.ingress-machine:checked')].map(input=>String(input.value));return ingressMachines.filter(machine=>selectedIds.includes(String(machine.id)))}function signatureLine(src,alt,width,height,text){return `<table role="presentation" style="border-collapse:collapse"><tr><td width="24" height="21" align="center" style="width:24px;height:21px;padding:0;text-align:center;vertical-align:middle"><img src="${escapeIngressHtml(src)}" alt="${alt}" width="${width}" height="${height}" style="display:block;width:${width}px;height:${height}px;margin:0 auto;border:0"></td><td style="padding:0;vertical-align:middle;color:#4b4b4b">${escapeIngressHtml(text)}</td></tr></table>`}function ingressSignatureMarkup(){const s=ingressSignature;return `<table class="email-signature" role="presentation" style="border-collapse:collapse;margin-top:8px;font-family:Arial,sans-serif;color:#252525"><tr><td contenteditable="false" style="width:125px;padding:0 14px 0 0;vertical-align:middle"><img src="${escapeIngressHtml(s.logo)}" alt="Life Maquinarias" width="112" style="display:block;width:112px;height:auto;border:0"></td><td contenteditable="false" style="width:4px;background:#ffc400;border-radius:3px;font-size:1px;line-height:1px">&nbsp;</td><td contenteditable="true" style="padding:0 0 0 16px;vertical-align:middle;font-size:13px;line-height:1.45"><div style="font-size:17px;font-weight:700">${escapeIngressHtml(s.name)}</div><div style="font-size:14px;font-weight:700;margin-bottom:7px">${escapeIngressHtml(s.position)}</div>${signatureLine(s.phoneIcon,'Teléfono',13,18,s.phone)}${signatureLine(s.emailIcon,'Correo',18,14,s.email)}${signatureLine(s.webIcon,'Web',17,17,s.website)}</td></tr></table>`}function ingressSignatureText(){const s=ingressSignature;return `${s.name}\n${s.position}\n${s.phone}\n${s.email}\n${s.website}`}
function updateIngressContacts(){const clientId=ingressClient.value,clientContacts=ingressContacts.filter(contact=>String(contact.client_id)===clientId);ingressContact.innerHTML='';ingressContact.disabled=!clientId;const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent=clientId?(clientContacts.length?'Seleccione el contacto':'Este cliente no tiene contactos registrados'):'Primero seleccione un cliente';ingressContact.append(placeholder);clientContacts.forEach(contact=>{const option=document.createElement('option');option.value=contact.id;option.textContent=contact.name+(contact.position?` — ${contact.position}`:'');option.dataset.name=contact.name;ingressContact.append(option)});if(clientContacts.length)ingressContact.value=String(clientContacts[0].id);if(window.jQuery&&jQuery(ingressContact).data('select2'))jQuery(ingressContact).trigger('change.select2');updateIngressMessage()}
function updateIngressMessage(){ingressPreview.dataset.edited='false';const contactOption=ingressContact.options[ingressContact.selectedIndex],contactName=contactOption?.dataset?.name||'[contacto del cliente]',workers=selectedIngressWorkers(),machines=selectedIngressMachines();document.getElementById('selectedWorkersCount').textContent=`${workers.length} seleccionado${workers.length===1?'':'s'}`;const workersMarkup=workers.length?workers.map(worker=>`<div class="preview-worker"><strong>${escapeIngressHtml(worker.name)}</strong><br><span>DNI: ${escapeIngressHtml(worker.document)} · Cargo: ${escapeIngressHtml(worker.position)}</span></div>`).join(''):'<div class="preview-worker preview-empty">Seleccione uno o varios trabajadores.</div>';const equipmentMarkup=machines.length?machines.map(machine=>`<div class="preview-worker"><strong>${escapeIngressHtml(machine.equipo)}${machine.serie_placa?' '+escapeIngressHtml(machine.serie_placa):''}</strong></div>`).join(''):'<div class="preview-worker preview-empty">Seleccione uno o varios equipos.</div>';ingressPreview.innerHTML=`<p>Buenos días, estimado Sr. <strong>${escapeIngressHtml(contactName)}</strong>:</p><p>Favor de apoyarme con las facilidades de salida el <strong>${escapeIngressHtml(ingressDateText(ingressDate.value))}</strong> del siguiente personal y equipo:</p>

<div class="preview-personal"><div class="preview-personal-title">Personal</div>${workersMarkup}</div>

<div class="preview-personal"><div class="preview-personal-title">Equipo</div>${equipmentMarkup}</div><p>Se adjunta documentación de personal y equipo.</p><p>Saludos,</p><p>Atentamente</p>${ingressSignatureMarkup()}`}
function ingressEditableHtml(){const copy=document.createElement('div');copy.innerHTML=ingressPreview.innerHTML;copy.querySelectorAll('.preview-personal').forEach(section=>{const title=section.querySelector('.preview-personal-title'),heading=document.createElement('p'),headingText=document.createElement('strong'),list=document.createElement('ul');headingText.textContent=title?.textContent?.trim()||'';heading.append(headingText);section.querySelectorAll('.preview-worker').forEach(worker=>{const item=document.createElement('li');item.innerHTML=worker.innerHTML;list.append(item)});section.replaceWith(heading,list)});const blocks=[...copy.children];blocks.forEach((block,index)=>{const isHeading=block.tagName==='P'&&['Personal','Equipo'].includes(block.textContent.trim());if(index===blocks.length-1||isHeading)return;if(block.tagName==='P'||block.tagName==='UL'){const spacer=document.createElement('p');spacer.innerHTML='&nbsp;';spacer.style.margin='0';spacer.style.lineHeight='12pt';block.after(spacer)}});copy.querySelectorAll('p').forEach(paragraph=>{paragraph.style.margin='0'});copy.querySelectorAll('ul').forEach(list=>{list.style.margin='0 0 0 20pt';list.style.padding='0'});return `<div style="font-family:Arial, sans-serif;font-size:11pt;color:#222;line-height:1.45">${copy.innerHTML}</div>`}
function ingressCopyPayload(){if(ingressPreview.dataset.edited==='true'){return{text:ingressPreview.innerText.trim(),html:ingressEditableHtml()}}const contactOption=ingressContact.options[ingressContact.selectedIndex],contactName=contactOption?.dataset?.name||'[contacto del cliente]',workers=selectedIngressWorkers(),machines=selectedIngressMachines(),date=ingressDateText(ingressDate.value),space='<p style="margin:0;line-height:12pt">&nbsp;</p>';const personalText=workers.length?workers.map(worker=>`• ${worker.name}\tDNI: ${worker.document}\tCargo: ${worker.position}`).join('\n'):'• Sin personal seleccionado.';const personalHtml=workers.length?workers.map(worker=>`<li><strong>${escapeIngressHtml(worker.name)}</strong>&nbsp;&nbsp;&nbsp; DNI: ${escapeIngressHtml(worker.document)}&nbsp;&nbsp;&nbsp; Cargo: ${escapeIngressHtml(worker.position)}</li>`).join(''):'<li>Sin personal seleccionado.</li>';const equipmentText=machines.length?machines.map(machine=>`• ${machine.equipo}${machine.serie_placa?' '+machine.serie_placa:''}`).join('\n'):'• Sin equipos seleccionados.';const equipmentHtml=machines.length?machines.map(machine=>`<li>${escapeIngressHtml(machine.equipo)}${machine.serie_placa?' '+escapeIngressHtml(machine.serie_placa):''}</li>`).join(''):'<li>Sin equipos seleccionados.</li>';const text=`Buenos días, estimado Sr. ${contactName}:\n\nFavor de apoyarme con las facilidades de salida el ${date} del siguiente personal y equipo:\n\nPersonal\n${personalText}\n\nEquipo\n${equipmentText}\n\nSe adjunta documentación de personal y equipo.\n\nSaludos,\n\nAtentamente\n\n${ingressSignatureText()}`;const html=`<div style="font-family:Arial, sans-serif;font-size:11pt;color:#222;line-height:1.45"><p style="margin:0">Buenos días, estimado Sr. <strong>${escapeIngressHtml(contactName)}</strong>:</p>${space}<p style="margin:0">Favor de apoyarme con las facilidades de salida el <strong>${escapeIngressHtml(date)}</strong> del siguiente personal y equipo:</p>${space}<p style="margin:0"><strong>Personal</strong></p><ul style="margin:0 0 0 20pt;padding:0">${personalHtml}</ul>${space}<p style="margin:0"><strong>Equipo</strong></p><ul style="margin:0 0 0 20pt;padding:0">${equipmentHtml}</ul>${space}<p style="margin:0">Se adjunta documentación de personal y equipo.</p>${space}<p style="margin:0">Saludos,</p>${space}<p style="margin:0">Atentamente</p>${space}${ingressSignatureMarkup()}</div>`;return{text,html}}
async function copyIngressMail(){const payload=ingressCopyPayload();try{if(navigator.clipboard?.write&&window.ClipboardItem){await navigator.clipboard.write([new ClipboardItem({'text/plain':new Blob([payload.text],{type:'text/plain'}),'text/html':new Blob([payload.html],{type:'text/html'})})])}else{await navigator.clipboard.writeText(payload.text)}}catch(error){const area=document.createElement('textarea');area.value=payload.text;document.body.append(area);area.select();document.execCommand('copy');area.remove()}Swal.fire({icon:'success',title:'Mensaje listo para Outlook',timer:1400,showConfirmButton:false})}
document.getElementById('copyIngressMessage').addEventListener('click',event=>{event.stopImmediatePropagation();copyIngressMail()},true);
function clearIngressComposer(){ingressDate.value=ingressDefaultDate;ingressClient.value='';ingressContact.innerHTML='<option value="">Primero seleccione un cliente</option>';ingressContact.disabled=true;document.querySelectorAll('.ingress-worker,.ingress-machine').forEach(input=>{input.checked=false});['workerSearch','machineSearch'].forEach(id=>{document.getElementById(id).value=''});filterIngressList(document.getElementById('workerSearch'),'#workerList .staff-option');filterIngressList(document.getElementById('machineSearch'),'#machineList .machine-option');if(window.jQuery){const clientSearch=jQuery(ingressClient),contactSearch=jQuery(ingressContact);if(clientSearch.data('select2'))clientSearch.val(null).trigger('change.select2');if(contactSearch.data('select2'))contactSearch.val(null).trigger('change.select2')}updateIngressMessage()}
document.getElementById('clearIngressMessage').addEventListener('click',clearIngressComposer);
function filterIngressList(input,selector){const term=input.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();document.querySelectorAll(selector).forEach(option=>{const source=(option.dataset.search||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();option.classList.toggle('d-none',!source.includes(term))})}
function bindIngressSearch(inputId,buttonId,selector){const input=document.getElementById(inputId),button=document.getElementById(buttonId),filter=()=>filterIngressList(input,selector);button.addEventListener('click',filter);input.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();filter()}})}
bindIngressSearch('workerSearch','workerSearchButton','#workerList .staff-option');bindIngressSearch('machineSearch','machineSearchButton','#machineList .machine-option');
ingressPreview.addEventListener('input',()=>{ingressPreview.dataset.edited='true'});ingressClient.addEventListener('change',updateIngressContacts);ingressContact.addEventListener('change',updateIngressMessage);ingressDate.addEventListener('change',updateIngressMessage);document.querySelectorAll('.ingress-worker,.ingress-machine').forEach(input=>input.addEventListener('change',updateIngressMessage));updateIngressMessage();
window.addEventListener('load',()=>{if(!window.jQuery||!jQuery.fn.select2)return;const clientSearch=jQuery('#ingressClient'),contactSearch=jQuery('#ingressContact');clientSearch.select2({theme:'bootstrap4',width:'100%',placeholder:'Buscar cliente por nombre o RUC',allowClear:true});contactSearch.select2({theme:'bootstrap4',width:'100%',placeholder:'Buscar contacto por nombre o cargo',allowClear:true});clientSearch.on('change',updateIngressContacts);contactSearch.on('change',updateIngressMessage)});
</script>
